N = int(input())
max_palindromic_cube = 0

def is_palindrome(s):
    return s == s[::-1]

# Iterate over possible cube roots up to the cube root of N
for number in range(1, int(N**(1/3)) + 2):
    cube = number**3
    if cube > N:
        break
    if is_palindrome(str(cube)):
        max_palindromic_cube = max(max_palindromic_cube, cube)

print(max_palindromic_cube)
